/* From Uiverse.io by Galahhad - Tags: input */
.__UIV_SCOPE__ .search-label {
  display: flex;
  align-items: center;
  box-sizing: border-box;
  position: relative;
  border: 1px solid transparent;
  border-radius: 12px;
  overflow: hidden;
  background: #3D3D3D;
  padding: 9px;
  cursor: text;
}

.__UIV_SCOPE__ .search-label:hover {
  border-color: gray;
}

.__UIV_SCOPE__ .search-label:focus-within {
  background: #464646;
  border-color: gray;
}

.__UIV_SCOPE__ .search-label input {
  outline: none;
  width: 100%;
  border: none;
  background: none;
  color: rgb(162, 162, 162);
}

.__UIV_SCOPE__ .search-label input:focus+.slash-icon,
.__UIV_SCOPE__ .search-label input:valid+.slash-icon {
  display: none;
}

.__UIV_SCOPE__ .search-label input:valid~.search-icon {
  display: block;
}

.__UIV_SCOPE__ .search-label input:valid {
  width: calc(100% - 22px);
  transform: translateX(20px);
}

.__UIV_SCOPE__ .search-label svg,
.__UIV_SCOPE__ .slash-icon {
  position: absolute;
  color: #7e7e7e;
}

.__UIV_SCOPE__ .search-icon {
  display: none;
  width: 12px;
  height: auto;
}

.__UIV_SCOPE__ .slash-icon {
  right: 7px;
  border: 1px solid #393838;
  background: linear-gradient(-225deg, #343434, #6d6d6d);
  border-radius: 3px;
  text-align: center;
  box-shadow: inset 0 -2px 0 0 #3f3f3f, inset 0 0 1px 1px rgb(94, 93, 93), 0 1px 2px 1px rgba(28, 28, 29, 0.4);
  cursor: pointer;
  font-size: 12px;
  width: 15px;
}

.__UIV_SCOPE__ .slash-icon:active {
  box-shadow: inset 0 1px 0 0 #3f3f3f, inset 0 0 1px 1px rgb(94, 93, 93), 0 1px 2px 0 rgba(28, 28, 29, 0.4);
  text-shadow: 0 1px 0 #7e7e7e;
  color: transparent;
}
